using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Structure;

var doc = Document;
// setup: an air terminal whose family places without a host (level- or work-plane-based),
// so it can drop at a point -- a face-based terminal would need a host face.
var symbol = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_DuctTerminal).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>()
    .First(s => s.Family.FamilyPlacementType == FamilyPlacementType.OneLevelBased
             || s.Family.FamilyPlacementType == FamilyPlacementType.WorkPlaneBased);
var level = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).First();

ElementId id = null;
Connector.WithTransaction(doc, () => {
    if (!symbol.IsActive) symbol.Activate();
    var at = doc.Create.NewFamilyInstance(new XYZ(5, 35, 10), symbol, level, StructuralType.NonStructural);
    id = at.Id;
});

var created = (FamilyInstance)doc.GetElement(id);
return new { id = id.ToString(), symbol = symbol.Name, family = symbol.Family.Name, placement = symbol.Family.FamilyPlacementType.ToString(), category = created.Category?.Name };
